import {broadExplorationPool,broadQuestionQueue,explorationPreview,broadFieldLabel,broadRoundQuestion} from './broad-exploration.js';
import {explorationExample} from './career-exploration-ui.js';
import {planMatchCandidates} from './plan-matches.js';
import {escapeHTML as h} from './html.js';
const link=r=>'#/journey/'+(r.expanded?'degree-check/'+r.id:'check-career/'+r.id+'/summary');
const name=r=>r.o.finance?.title||r.o.title;
export function broadExplorationEntry(){return '<section class="guide-input-panel broad-entry"><p class="eyebrow">NEW · EXPLORE ACROSS FIELDS</p><h2>Let’s discover what might fit.</h2><p>Start with a few examples across different kinds of work. Exploring one keeps the others available. You can still browse by field below.</p><a class="button" href="#/journey/discover">Explore possibilities across fields →</a><p class="small">Discovery pilot · your existing answers and matches stay available.</p></section>';}
export function broadExplorationPage(s,route){
 const pool=broadExplorationPool(s),open=pool.rows.filter(r=>!r.declined),preview=explorationPreview(pool.rows),data=planMatchCandidates(s),top=new Set(data.top.map(r=>r.id));
 const intro='<section class="degree-inventory broad-discovery"><a href="#/journey/pathways">← All exploration options</a><p class="eyebrow">DISCOVER POSSIBILITIES · PILOT</p><h1>Keep your possibilities open.</h1><p>We consider careers across fields. A field card, your current skill confidence, and your lifestyle budget do not decide which possibilities you can explore here. Strong matches still need supporting answers.</p>';
 const current='<section class="guide-input-panel"><h2>Your supported matches</h2>'+(data.top.length?'<ul>'+data.top.map(r=>'<li>'+h(name(r))+'</li>').join('')+'</ul>':'<p>No confirmed Top yet. It is fine to keep exploring.</p>')+'<a href="#/journey/expanded-matches">Compare your matches, preparation and lifestyle →</a></section>';
 if(route.includes('/reflect/')){
  const turn=Math.max(0,Math.min(1200,Number(route.split('/')[3])||0)),entry=s.profileJourney?.broadRound?broadRoundQuestion(s):broadQuestionQueue(s,{limit:1})[0];
  if(!entry)return intro+'<h2>You’ve reached the end of the unasked examples.</h2><p>Some interests may still be uncertain. Read about the work or try a small experience before revisiting them. We do not turn uncertainty into a Yes.</p>'+current+'<a class="button" href="#/journey/discover">Review all possibilities →</a></section>';
  const row=pool.rows.find(r=>r.id===entry.careerId),q=entry.q,binary=entry.expanded||q.kind==='core-work';
  return intro+'<p class="profile-progress-label">Example '+(turn%12+1)+' in this round · pause or compare at any time</p>'+explorationExample(q.id)+'<h2>'+h(q.prompt)+'</h2><p>Focus on what you would like to learn. Experience is not required.</p><form id="broad-reflection">'+(!binary?'<p>Choose any that appeal, then save your choices.</p><div class="profile-multi-grid">'+q.options.map(o=>'<label class="guide-input-panel"><input type="checkbox" name="broad-choice" value="'+h(o.id)+'"> '+h(o.text)+'</label>').join('')+'</div>':'')+'<div class="guide-actions">'+(binary?[['yes','I would like to learn this'],['no','This does not interest me']]:[['selected','Save my choices'],['no','None of these interests me']]).concat([['unsure','I’m not sure'],['unfamiliar','I need to learn more']]).map(([value,label])=>'<button type="button" class="button secondary" data-action="broad-reflect" data-career="'+h(row.id)+'" data-question="'+h(q.id)+'" data-response="'+value+'" data-turn="'+turn+'">'+label+'</button>').join('')+'</div><p id="broad-answer-error" role="status"></p></form><details class="guide-input-panel"><summary>See where this example could lead</summary><h3>'+h(name(row))+'</h3><p>'+h(row.o.summary)+'</p><p>'+h(row.routes.map(r=>r.label).join(' · '))+'</p><p>Exploration invitation. Other interests, responsibilities and preparation still need consideration.</p></details><a href="#/journey/discover">Pause and review possibilities →</a></section>';
 }
 const card=r=>'<article class="pathway-card"><p class="eyebrow">'+h(broadFieldLabel(r.family))+'</p><h3>'+h(name(r))+'</h3><p>'+h(r.o.summary)+'</p><p>'+h(r.routes.map(r=>r.label).join(' · '))+'</p><p><strong>'+(top.has(r.id)?'Current Top match':r.declined?'An essential interest was declined':r.confirmed?'Defining interests supported; other checks apply':r.unasked.length?'Some interests have not been asked yet':'More clarification needed')+'</strong></p><a class="button secondary" href="'+link(r)+'">'+(r.declined?'Review your reflection':'Explore and clarify')+' →</a></article>';
 return intro+(pool.status!=='ready'?'<p>Your interest pattern is still open. Browse freely and try a few examples; we won’t assign a strong match from an unclear pattern.</p>':'<p>'+open.length+' interest-aligned possibilities remain open across the inventory. These are invitations, not '+open.length+' confirmed matches.</p><div class="guide-actions">'+(broadQuestionQueue(s,{limit:1}).length?'<button class="button" data-action="broad-start">Try a short round of examples →</button>':'')+'<a class="button secondary" href="#/journey/expanded-matches">Compare current matches →</a></div><p>Up to 12 new reflections per round. Exact answers already saved are reused; uncertain answers stay uncertain. You can stop whenever you want.</p><h2>Starting possibilities across fields</h2><div class="pathway-trio">'+preview.map(card).join('')+'</div><details class="guide-input-panel"><summary>Browse all '+pool.rows.length+' aligned possibilities, including declined interests</summary><p>This list is larger than the starting cards. A declined interest is kept for review and does not become a Top match automatically.</p><div class="library-card-grid">'+pool.rows.map(card).join('')+'</div></details>')+current+'<div class="guide-actions"><a href="#/degree-careers">Browse all college and graduate careers →</a><a href="#/journey/pathways">Browse by field →</a><a href="#/journey/profile-review">Review your interests →</a></div></section>';
}
